// Package iossimulator_arm64 carries the prebuilt FFmpeg shared libraries for the iOS simulator on Apple silicon.
//
// It exposes no Go API. goffmpeg imports it for its side effects: the
// cgo directives in libav.go and libav_swscale.go, generated by goffmpeg's
// make sync-libs, link this platform's shared FFmpeg libraries from shared/.
// That is how one small module per platform replaces vendoring every
// platform's artifacts into goffmpeg itself.
package iossimulator_arm64
